package com.travelbird.ai.service;
import com.travelbird.ai.entity.BackendAiJobStatus;import com.travelbird.ai.repository.AiRecommendationJobRepository;import com.travelbird.global.error.AiJobFailureCode;import java.time.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AiJobTimeoutService{private final AiRecommendationJobRepository jobs;private final Clock clock;private final int seconds;public AiJobTimeoutService(AiRecommendationJobRepository j,Clock c,@Value("${app.ai.callback-timeout-seconds:180}")int s){jobs=j;clock=c;seconds=s;}@Transactional public void failTimedOutJobs(){var now=LocalDateTime.now(clock);for(var candidate:jobs.findByStatusAndStartedAtLessThanEqual(BackendAiJobStatus.PROCESSING,now.minusSeconds(seconds))){var job=jobs.findByIdForUpdate(candidate.getId()).orElse(null);if(job!=null&&job.getStatus()==BackendAiJobStatus.PROCESSING&&job.getStartedAt()!=null&&!job.getStartedAt().plusSeconds(seconds).isAfter(now))job.fail(AiJobFailureCode.AI_CALLBACK_TIMEOUT,"AI callback was not received within "+seconds+" seconds",true,now); }}}
